from __future__ import annotations

from exo import *
from exo.API_scheduling import *  # scheduling primitives (divide_loop, unroll_loop, simplify, ...)
from exo.libs.memories import DRAM
from exo.core.extern import Extern, _EErr


# Extern for the PolyBench SQRT_FUN macro.
# We cannot call SQRT_FUN directly from Exo, so we route it through an Extern,
# which the backend lowers to the appropriate C macro invocation.
class _SqrtFun(Extern):
    def __init__(self):
        # Name as it appears in printed Exo code
        super().__init__("sqrt_fun")

    def typecheck(self, args):
        if len(args) != 1:
            raise _EErr(f"expected 1 argument, got {len(args)}")

        arg_type = args[0].type
        # Require a real scalar (matches PolyBench's SQRT_FUN usage)
        if not arg_type.is_real_scalar():
            raise _EErr(
                f"expected argument to be a real scalar value, but got type {arg_type}"
            )
        return arg_type

    def compile(self, args, prim_type):
        # Lower to the PolyBench SQRT_FUN macro (which resolves to sqrt / sqrtf, etc.).
        # prim_type is the C primitive type corresponding to DATA_TYPE.
        return f"SQRT_FUN(({prim_type}){args[0]})"

    def globl(self, prim_type):
        # Ensure SQRT_FUN is visible when compiling the generated kernel.
        # cholesky.h (transitively) pulls in polybench.h where SQRT_FUN is defined.
        return '#include "cholesky.h"'

    def interpret(self, args):
        import math
        return math.sqrt(args[0])


sqrt_fun = _SqrtFun()


@proc
def kernel_cholesky(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    # Direct transcription of the PolyBench Cholesky factorization:
    #   for (i = 0; i < n; i++)
    #     for (j = 0; j < i; j++) {
    #       for (k = 0; k < j; k++)
    #         A[i][j] -= A[i][k] * A[j][k];
    #       A[i][j] /= A[j][j];
    #     }
    #     for (k = 0; k < i; k++)
    #       A[i][i] -= A[i][k] * A[i][k];
    #     A[i][i] = SQRT_FUN(A[i][i]);
    #
    # We simply rename the two different k-loops to k1 and k2 so that
    # we can schedule them independently.
    for i in seq(0, n):
        # Off-diagonal elements: j < i
        for j in seq(0, i):
            for k1 in seq(0, j):
                A[i, j] = A[i, j] - A[i, k1] * A[j, k1]
            A[i, j] = A[i, j] / A[j, j]

        # Diagonal element: j == i
        for k2 in seq(0, i):
            A[i, i] = A[i, i] - A[i, k2] * A[i, k2]

        A[i, i] = sqrt_fun(A[i, i])


# -------------------------
# Scheduling / optimization
# -------------------------
#
# The core computation consists of two inner-product style loops:
#   - k1-loop: A[i,j] -= A[i,k1] * A[j,k1]   (j < i)
#   - k2-loop: A[i,i] -= A[i,k2] * A[i,k2]
#
# We make these more friendly to the C compiler and to the CPU front-end by:
#   1. Dividing each k-loop by a small constant factor (VL = 4) using divide_loop.
#      This exposes a regular inner loop of fixed trip count (the "vector-length").
#   2. Fully unrolling that fixed-size inner loop with unroll_loop.
#      This increases instruction-level parallelism and gives the backend a
#      straight-line sequence of multiply-accumulate operations that is easy
#      to auto-vectorize.
#
# The division and unrolling preserve the *sequential* order of k1/k2, so the
# floating-point result is bitwise-identical to the original loop nest.
#
# Finally, we call simplify to clean up any trivial guards and constant
# expressions introduced by tiling.
VL = 4  # unrolling / vectorization-friendly factor

cholesky_opt = kernel_cholesky

# 1) Tile + unroll the off-diagonal update's k1-loop.
cholesky_opt = divide_loop(
    cholesky_opt,
    cholesky_opt.find_loop("k1"),
    VL,
    ["k1_o", "k1_i"],
    tail="guard",
)
cholesky_opt = unroll_loop(
    cholesky_opt,
    cholesky_opt.find_loop("k1_i"),
)

# 2) Tile + unroll the diagonal update's k2-loop.
cholesky_opt = divide_loop(
    cholesky_opt,
    cholesky_opt.find_loop("k2"),
    VL,
    ["k2_o", "k2_i"],
    tail="guard",
)
cholesky_opt = unroll_loop(
    cholesky_opt,
    cholesky_opt.find_loop("k2_i"),
)

# 3) Simplify the resulting IR (constant folding, dead branches/loops, etc.).
cholesky_opt = simplify(cholesky_opt)

# Expose the optimized version under the original kernel name so that the
# generated C function is still called `kernel_cholesky` from the driver.
kernel_cholesky = cholesky_opt
EXO END
